public final class NaturalVillageR3GameTests {
 public static String phase(){return System.getProperty("sagadyssey.society.phase","");}
 @net.neoforged.bus.api.SubscribeEvent public static void install(net.neoforged.neoforge.event.server.ServerStartedEvent e){if(!(e.getServer() instanceof GameTestServer)||!phase().startsWith("r3-"))return;var l=e.getServer().overworld();l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.RANDOM_TICK_SPEED, 3,e.getServer());l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.ADVANCE_TIME, true,e.getServer());l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.SPAWN_MOBS, false,e.getServer());try{if(phase().endsWith("-restart")){var marker=NbtIo.readCompressed(e.getServer().getWorldPath(LevelResource.ROOT).resolve("r3-checkpoint.nbt"),NbtAccounter.unlimitedHeap());var world=NbtIo.readCompressed(e.getServer().getWorldPath(LevelResource.ROOT).resolve("level.dat"),NbtAccounter.unlimitedHeap()).getCompoundOrEmpty("Data");e.getServer().getWorldData().overworldData().setGameTime(Math.max(world.getLongOr("Time", 0L),marker.getLongOr("Time", 0L))+1);e.getServer().getWorldData().overworldData().setDayTime(world.getLongOr("DayTime", 0L)+1);}
 l.getStructureManager().getOrCreate(Identifier.parse("sagadyssey_society_r3:empty")).load(l.holderLookup(Registries.BLOCK),TagParser.parseCompoundFully("{size:[16,6,16],entities:[],blocks:[],palette:[{Name:'minecraft:air'}]}"));}catch(Exception x){throw new IllegalStateException(x);}}
 @GameTestGenerator public static Collection<TestFunction> tests(){return switch(phase()){
  case "r3-growth"->List.of(test("resource_backed_bed_and_mid_project_succession",NaturalVillageR3GameTests::growth,80000));
  case "r3-decline"->List.of(test("persistent_actual_shortage_pauses_work_without_deleting_people",NaturalVillageR3GameTests::decline,90000));
  case "r3-distribution"->List.of(test("seeded_versioned_groups_villages_and_federation_coexist",NaturalVillageR3GameTests::distribution,20000));
  case "r3-conflict"->List.of(test("real_overdue_trade_funds_existing_people_and_durable_ceasefire",SocietyConflictGameTests::run,80000));
  case "r3-conflict-restart"->List.of(test("ceasefire_and_unpaid_obligation_after_independent_restart",SocietyConflictGameTests::restart,60000));
  case "r3-growth-restart"->List.of(test("same_inherited_project_and_real_bed_after_restart",NaturalVillageR3GameTests::growthRestart,20000));
  case "r3-performance"->List.of(test("four_actual_sites_bounded_remote_backlog_and_memory",SocietyRegionPerformanceGameTests::run,300000));
  case "r3-participation"->List.of(test("ordinary_commands_petition_without_public_asset_authority",SocietyOrdinaryParticipationGameTests::run,1000));
  case "r3-autonomous"->List.of(test("natural_production_trade_migration_and_growth_without_food_fixture",SocietyAutonomousGrowthGameTests::run,420000));
  case "r3-player-away"->List.of(test("player_membership_never_becomes_an_offline_npc_meal",SocietyPlayerAwayGameTests::run,160000));
  case "r3-withdraw"->List.of(test("withdrawn_work_authority_preserves_cost_and_original_position",SocietyConflictGameTests::run,60000));
  case "r3-region-limit"->List.of(test("fifth_discovery_cannot_expand_the_capped_region",SocietyRegionLimitGameTests::run,1200));
  default->List.of();};}
 private static TestFunction test(String name,java.util.function.Consumer<GameTestHelper> f,int limit){return new TestFunction("society_r3",name,"sagadyssey_society_r3:empty",limit,0,true,f);}
 public static void gift(GameTestHelper h,UUID actor,UUID from,Container source,UUID to,Container target,String item,int quantity){var s=h.getLevel().getServer();var rights=RightsStateData.get(s);long now=h.getLevel().getGameTime();var request=new TransferRequest(UUID.randomUUID(),SubjectRef.character(actor),TransferIntent.GIFT,List.of(new TransferLeg(from,to,new ItemFingerprint("minecraft:"+item,0),quantity)),List.of(new ExpectedRevision(from,rights.context(from).revision()),new ExpectedRevision(to,rights.context(to).revision())),"controlled fixture transfers existing generated goods without a grant",now);var result=new TransferService(rights,TransferLedgerData.get(s)).submit(request,Map.of(from,new TransferEndpoint(from,source),to,new TransferEndpoint(to,target)),now);h.assertTrue(result.successful(),"actual fixture gift: "+result.reason());}
 private static int count(Container c,String item){return c==null?0:SupplyFlowService.count(c,new ItemFingerprint("minecraft:"+item,0));}
 private static int food(GameTestHelper h,List<NaturalVillageBuilding> villages){int n=0;var s=h.getLevel().getServer();for(var b:villages){for(int i=0;i<NaturalVillageLayout.stores(b).size();i++)n+=count(NaturalPolityData.inventory(s,b,i),"carrot");for(int i=0;i<3;i++){var a=NaturalVillageR1GameTests.actor(h.getLevel(),b,i);if(a!=null)n+=count(a.getPersonalInventory(),"carrot")+count(a.getTransportInventory(),"carrot");}}return n;}
 private static void growth(GameTestHelper h){var l=h.getLevel();var s=l.getServer();var farm=NaturalVillageR1GameTests.fixture(h,0,NaturalVillageLayout.FARM_V2);var wood=NaturalVillageR1GameTests.fixture(h,96,NaturalVillageLayout.WOOD_V2);int[] stage={0},last={-1};boolean[] died={false};var meals=new HashSet<String>();UUID old=NaturalVillageLifeData.person(farm,1),heir=NaturalVillageLifeData.person(farm,0);
  h.onEachTick(()->{if(last[0]==s.getTickCount())return;last[0]=s.getTickCount();var data=NaturalPolityData.get(s);for(var b:List.of(farm,wood))NaturalVillageR1GameTests.observe(l,b,meals);
   if(s.getTickCount()%12000==0)Sagadyssey.LOGGER.info("R3_GROWTH_PROGRESS stage={} sites={}",stage[0],data.sites().stream().map(t->t.getStringOr("Condition", "")+":"+t.getCompoundOrEmpty("Project")).toList());
   if(stage[0]==0&&h.getTick()>=220){var timber=NaturalPolityData.inventory(s,wood,2);if(count(timber,"oak_log")<1)return;for(int i=0;i<3;i++)NaturalVillageR1GameTests.actor(l,farm,i).setNoAi(true);var pantry=NaturalPolityData.inventory(s,farm,1);var pub=NaturalPolityData.inventory(s,farm,3);var farmer=NaturalVillageR1GameTests.actor(l,farm,0);var woodhead=NaturalVillageR1GameTests.actor(l,wood,0);var forester=NaturalVillageR1GameTests.actor(l,wood,2);
    gift(h,farmer.getCharacterId(),ContainerIds.npcPersonal(farmer.getCharacterId()),farmer.getPersonalInventory(),NaturalVillageEconomyData.storeId(farm,3),pub,"carrot",4);gift(h,farmer.getCharacterId(),ContainerIds.npcPersonal(farmer.getCharacterId()),farmer.getPersonalInventory(),NaturalVillageEconomyData.storeId(farm,1),pantry,"carrot",12);gift(h,woodhead.getCharacterId(),ContainerIds.npcPersonal(woodhead.getCharacterId()),woodhead.getPersonalInventory(),NaturalVillageEconomyData.storeId(farm,1),pantry,"carrot",16);gift(h,forester.getCharacterId(),NaturalVillageEconomyData.storeId(wood,2),timber,NaturalVillageEconomyData.storeId(farm,1),pantry,"oak_log",1);
    h.assertTrue(NaturalHouseholdMigrationData.get(s).request(s,wood,farm,NaturalVillageLifeData.person(wood,1)).equals("ACCEPTED"),"housing pressure comes from an actual original household caravan");stage[0]=1;
   }
   if(stage[0]==1){if(NaturalHouseholdMigrationData.get(s).moves().stream().noneMatch(t->t.getStringOr("State", "").equals("DONE")))return;for(int i=0;i<3;i++)NaturalVillageR1GameTests.actor(l,wood,i).setNoAi(true);NaturalVillageR1GameTests.actor(l,farm,2).setNoAi(false);h.assertTrue(NaturalPolityData.population(s,farm).size()==6,"six actual arrivals create housing pressure");stage[0]=2;}
   if(stage[0]==2){var row=data.site(farm.settlementId());var project=row.getCompoundOrEmpty("Project");if(!died[0]&&project.getStringOr("Stage", "").equals("PLANKS")&&project.getIntOr("Work", 0)>=20){h.assertTrue(project.getIntOr("PopulationAtApproval", 0)==6&&project.getIntOr("AuthorizedFoodAtApproval", 0)>=20,"project is caused by recorded resource surplus and housing pressure");var n=NaturalVillageR1GameTests.actor(l,farm,1);n.hurt(l.damageSources().genericKill(),Float.MAX_VALUE);died[0]=true;return;}
    if(!project.getStringOr("Stage", "").equals("DONE"))return;h.assertTrue(died[0]&&PoliticalStateData.get(s).titleHolder(farm.settlementId()).equals(heir)&&!data.authorized(s,farm,old)&&data.authorized(s,farm,heir),"real death uses existing heir, revokes old public grant and continues the same project");
    var pub=NaturalPolityData.inventory(s,farm,3);h.assertTrue(count(pub,"oak_planks")==1&&count(pub,"oak_log")==0&&count(pub,"white_wool")==0&&count(pub,"white_bed")==0&&row.getIntOr("ExtraBeds", 0)==1&&l.getBlockState(NaturalVillageLayout.at(farm,new BlockPos(8,1,18))).is(Blocks.WHITE_BED),"one real bed with exact crafting inputs and one remaining plank");
    int before=count(pub,"carrot");h.assertTrue(!data.relief(s,farm,UUID.randomUUID(),NaturalVillageLifeData.home(farm)).equals("DONE")&&count(pub,"carrot")==before,"outsider cannot spend public goods");h.assertTrue(data.relief(s,farm,heir,NaturalVillageLifeData.home(farm)).equals("DONE")&&count(pub,"carrot")==before-2,"heir approves actual two-carrot public allocation");h.assertTrue(data.relief(s,farm,heir,NaturalVillageLifeData.home(farm)).equals("DONE")&&count(pub,"carrot")==before-2,"repeat request never repeats allocation");
    h.assertTrue(food(h,List.of(farm,wood))+meals.size()+4==32,"all generated carrots = remaining physical carrots + receipted individual meals + four construction rations");var reload=NaturalPolityData.load(data.save(new CompoundTag(),s.registryAccess()),s.registryAccess());h.assertTrue(reload.site(farm.settlementId()).getCompoundOrEmpty("Project").getStringOr("Stage", "").equals("DONE")&&reload.decisions().size()==1,"reloaded institution retains the original project and public decision");Sagadyssey.LOGGER.info("R3_GROWTH_GOVERNANCE_ACCEPT bed=1 logInput=1 woolInput=3 constructionMeals=4 remainingPlanks=1 individualMeals={} physicalCarrots={} originalLeaderDead=true inheritedProject=true",meals.size(),food(h,List.of(farm,wood)));checkpoint(h,List.of(farm,wood));h.succeed();stage[0]=3;
   }
  });
 }
 public static void checkpoint(GameTestHelper h,List<NaturalVillageBuilding> villages){var t=new CompoundTag();var list=new ListTag();for(var b:villages)list.add(NaturalVillageLifeData.get(h.getLevel().getServer()).village(b.buildingKey()));t.put("Villages",list);t.putLong("Time",h.getLevel().getGameTime());try{NbtIo.writeCompressed(t,h.getLevel().getServer().getWorldPath(LevelResource.ROOT).resolve("r3-checkpoint.nbt"));h.getLevel().getServer().saveEverything(true,true,true);}catch(Exception e){throw new IllegalStateException(e);}}
 public static List<NaturalVillageBuilding> restored(GameTestHelper h){try{var t=NbtIo.readCompressed(h.getLevel().getServer().getWorldPath(LevelResource.ROOT).resolve("r3-checkpoint.nbt"),NbtAccounter.unlimitedHeap());var list=new ArrayList<NaturalVillageBuilding>();for(var e:MinecraftApi.listOfType(t, "Villages",Tag.TAG_COMPOUND)){var b=NaturalVillageLifeData.decode((CompoundTag)e);list.add(b);NaturalVillageR1GameTests.visiting(h.getLevel(),b,true);}return list;}catch(Exception e){throw new IllegalStateException(e);}}
 private static void growthRestart(GameTestHelper h){var l=h.getLevel();var s=l.getServer();var villages=restored(h);var farm=villages.getFirst();int[] last={-1};h.onEachTick(()->{if(last[0]==s.getTickCount())return;last[0]=s.getTickCount();var d=NaturalVillageEconomyData.get(s);if(villages.stream().anyMatch(b->!d.row(b.buildingKey()).getStringOr("Phase", "").equals("NEAR")))return;if(h.getTick()<300)return;var data=NaturalPolityData.get(s);var row=data.site(farm.settlementId());var heir=NaturalVillageLifeData.person(farm,0);h.assertTrue(row.getCompoundOrEmpty("Project").getStringOr("Stage", "").equals("DONE")&&row.getIntOr("ExtraBeds", 0)==1&&PoliticalStateData.get(s).titleHolder(farm.settlementId()).equals(heir)&&NaturalVillageR1GameTests.actor(l,farm,1)==null&&!CharacterRegistryData.get(s).byId(NaturalVillageLifeData.person(farm,1)).alive(),"same bed, original deceased leader and existing heir survive independent JVM restart");h.assertTrue(count(NaturalPolityData.inventory(s,farm,3),"oak_planks")==1&&data.decisions().size()==1&&data.relief(s,farm,heir,NaturalVillageLifeData.home(farm)).equals("DONE"),"repeated public decision reuses its settled identity");Sagadyssey.LOGGER.info("R3_GROWTH_RESTART_ACCEPT sameProject=true extraBeds=1 decisions=1 deceasedLeaderNotRespawned=true");h.succeed();});}
 private static void decline(GameTestHelper h){var l=h.getLevel();var s=l.getServer();var b=NaturalVillageR1GameTests.fixture(h,0,NaturalVillageLayout.FARM_V2);int[] stage={0},last={-1};long[] start={0};h.onEachTick(()->{if(last[0]==s.getTickCount())return;last[0]=s.getTickCount();var data=NaturalPolityData.get(s);
  if(stage[0]==0&&h.getTick()>=220){for(int i=0;i<3;i++){var n=NaturalVillageR1GameTests.actor(l,b,i);n.setNoAi(true);NpcLifeData.get(s).setHunger(n.getCharacterId(),950,l.getGameTime());}var n=NaturalVillageR1GameTests.actor(l,b,0);var bag=ContainerIds.npcPersonal(n.getCharacterId());h.assertTrue(new ConsumptionService(RightsStateData.get(s)).consume(bag,n.getPersonalInventory(),SubjectRef.character(n.getCharacterId()),new ItemFingerprint("minecraft:carrot",0),16,"controlled real depletion of generated reserve",l.getGameTime()).successful(),"shortage scenario accounts for exhaustion of initial food");start[0]=l.getGameTime();stage[0]=1;}
  if(stage[0]==1&&l.getGameTime()-start[0]>=50000){var row=data.site(b.settlementId());h.assertTrue(row.getStringOr("Condition", "").equals("DECLINING")&&!row.contains("Project")&&NaturalPolityData.population(s,b).size()==3&&food(h,List.of(b))==0,"persistent actual shortage declines without hidden rescue or deleting residents");h.assertTrue(NaturalPolityData.paused(s,NaturalVillageLifeData.person(b,0)),"publicly supported productive work is suspended for the recorded cause");stage[0]=2;}
  if(stage[0]==2&&l.getGameTime()-start[0]>=74000){h.assertTrue(data.site(b.settlementId()).getStringOr("Condition", "").equals("DECLINING")&&food(h,List.of(b))==0&&NaturalPolityData.population(s,b).size()==3,"decline persists without an artificial timer recovery, food or population removal");Sagadyssey.LOGGER.info("R3_DECLINE_ACCEPT shortageTicks={} people=3 food=0 hiddenGrants=0",l.getGameTime()-start[0]);h.succeed();stage[0]=3;}
 });}
 private static List<String> draws(GameTestHelper h,long seed){var l=h.getLevel();var g=l.getChunkSource().getGenerator();var structure=l.registryAccess().lookupOrThrow(Registries.STRUCTURE).get(NaturalVillageBuilding.SUPPORTED).orElseThrow();var out=new ArrayList<String>();for(int i=0;i<32;i++){var cp=new net.minecraft.world.level.ChunkPos(1000+i*16,2000);var st=structure.value().generate(structure, l.dimension(), l.registryAccess(),g,g.getBiomeSource(),l.getChunkSource().randomState(),l.getStructureManager(),seed,cp,0,l,biome->true);out.add(st.isValid()?NaturalVillageR1GameTests.template(l,st).toString():"invalid");}return out;}
 private static void distribution(GameTestHelper h){var l=h.getLevel();var s=l.getServer();var farm=NaturalVillageR1GameTests.fixture(h,0,NaturalVillageLayout.FARM_V2);var wood=NaturalVillageR1GameTests.fixture(h,96,NaturalVillageLayout.WOOD_V2);var group=NaturalVillageR1GameTests.fixture(h,512,NaturalVillageLayout.LIVING);var independent=NaturalVillageR1GameTests.fixture(h,896,NaturalVillageLayout.FARM_V2);var villages=List.of(farm,wood,group,independent);h.runAfterDelay(300,()->{var data=NaturalPolityData.get(s);var a=draws(h,7019);h.assertTrue(a.equals(draws(h,7019))&&!a.equals(draws(h,7020))&&new HashSet<>(a).containsAll(Set.of(NaturalVillageLayout.LIVING.toString(),NaturalVillageLayout.FARM_V2.toString(),NaturalVillageLayout.WOOD_V2.toString())),"actual Jigsaw pools reproduce at a fixed seed and differ across seeds");
  h.assertTrue(data.site(group.settlementId()).getStringOr("Kind", "").equals("GROUP")&&!data.site(group.settlementId()).contains("Realm")&&data.site(independent.settlementId()).getStringOr("Kind", "").equals("VILLAGE")&&!data.site(independent.settlementId()).contains("Realm"),"an independent group and village coexist without timer promotion");String realm=data.site(farm.settlementId()).getStringOr("Realm", "");h.assertTrue(!realm.isBlank()&&realm.equals(data.site(wood.settlementId()).getStringOr("Realm", ""))&&PoliticalStateData.get(s).ruler(realm).equals(NaturalVillageLifeData.person(farm,1))&&PoliticalStateData.get(s).liegeOf(NaturalVillageLifeData.person(wood,1)).equals(NaturalVillageLifeData.person(farm,1)),"state is an existing ruler/fealty relationship among real distinct settlements");
  var before=data.save(new CompoundTag(),s.registryAccess());data.enroll(s);h.assertTrue(before.equals(data.save(new CompoundTag(),s.registryAccess())),"re-exploration does not generate another organization or reroll its members");h.assertTrue(villages.stream().flatMap(b->NaturalPolityData.population(s,b).stream()).distinct().count()==12&&NaturalVillageEconomyData.get(s).rows().size()==4,"four real sites retain exactly twelve original people, counted once");Sagadyssey.LOGGER.info("R3_DISTRIBUTION_ACCEPT sites=4 people=12 group=1 independentVillage=1 stateMembers=2 seed7019={} seed7020={}",a,draws(h,7020));h.succeed();});}
}
